const defaultLanguage = 'hu';
let currentLanguage = 'hu';

try {
  currentLanguage = localStorage.getItem('errormii-language') || defaultLanguage;
} catch (error) {
  currentLanguage = defaultLanguage;
}

function getTranslateKey(element) {
  return element.dataset.i18n || element.dataset.translate || element.getAttribute('data-i18n') || element.getAttribute('data-translate');
}

function renderWorkshopPrinciples(lang) {
  const container = document.getElementById('workshopPrinciples');
  const heading = document.getElementById('workshopPrinciplesTitle');
  const content = workshopPrinciples[lang];
  if (!container || !heading || !content) return;

  heading.textContent = content.title;
  const fragment = document.createDocumentFragment();
  content.items.forEach((item, index) => {
    const article = document.createElement('article');
    article.className = 'workshop-principle';

    const title = document.createElement('h5');
    title.className = 'workshop-principle-title';
    const number = document.createElement('span');
    number.className = 'workshop-principle-number';
    number.textContent = `${String(index + 1).padStart(2, '0')}.`;
    const name = document.createElement('span');
    name.textContent = item.title;
    title.append(number, name);

    article.append(title);

    fragment.append(article);
  });
  container.replaceChildren(fragment);
}

function setLanguage(lang) {
  const safeLang = translations[lang] ? lang : defaultLanguage;
  currentLanguage = safeLang;

  try {
    localStorage.setItem('errormii-language', currentLanguage);
  } catch (error) {
    // Ignore storage errors in restricted browsers.
  }

  document.documentElement.lang = currentLanguage;

  document.querySelectorAll('[data-i18n], [data-translate]').forEach((element) => {
    const key = getTranslateKey(element);
    const translation = translations[currentLanguage] && translations[currentLanguage][key];
    if (!translation) return;
    element.textContent = translation;
  });

  document.querySelectorAll('[data-i18n-html]').forEach((element) => {
    const key = element.dataset.i18nHtml;
    const translation = translations[currentLanguage] && translations[currentLanguage][key];
    if (!translation) return;
    element.innerHTML = translation;
  });

  document.querySelectorAll('[data-i18n-aria-label]').forEach((element) => {
    const translation = translations[currentLanguage] && translations[currentLanguage][element.dataset.i18nAriaLabel];
    if (translation) element.setAttribute('aria-label', translation);
  });

  renderWorkshopPrinciples(currentLanguage);

  document.querySelectorAll('.lang-btn').forEach((button) => {
    const active = button.dataset.lang === currentLanguage;
    button.classList.toggle('active', active);
    button.setAttribute('aria-pressed', String(active));
  });

  const year = document.getElementById('year');
  if (year) {
    year.textContent = new Date().getFullYear();
  }
}

function bindLanguageButtons() {
  document.querySelectorAll('.lang-btn').forEach((button) => {
    button.addEventListener('click', () => {
      setLanguage(button.dataset.lang || 'hu');
    });
  });
}

bindLanguageButtons();
setLanguage(currentLanguage);

(() => {
  const carousel = document.querySelector('.give-take-essay');
  if (!carousel) return;

  const slides = [...carousel.querySelectorAll('.give-take-slide')];
  const previous = carousel.querySelector('.give-take-prev');
  const next = carousel.querySelector('.give-take-next');
  const count = carousel.querySelector('.give-take-pagination-count');
  let current = 0;

  function showSlide(index) {
    current = Math.max(0, Math.min(index, slides.length - 1));
    slides.forEach((slide, slideIndex) => {
      const active = slideIndex === current;
      slide.hidden = !active;
      slide.setAttribute('aria-hidden', String(!active));
    });

    previous.disabled = current === 0;
    next.disabled = current === slides.length - 1;
    previous.setAttribute('aria-controls', slides[Math.max(0, current - 1)].id);
    next.setAttribute('aria-controls', slides[Math.min(slides.length - 1, current + 1)].id);
    count.textContent = `${String(current + 1).padStart(2, '0')} / ${String(slides.length).padStart(2, '0')}`;
  }

  previous.addEventListener('click', () => {
    showSlide(current - 1);
    next.focus();
  });
  next.addEventListener('click', () => {
    showSlide(current + 1);
    previous.focus();
  });
  carousel.addEventListener('keydown', (event) => {
    if (event.key === 'ArrowLeft' && current > 0) {
      event.preventDefault();
      showSlide(current - 1);
      next.focus();
    } else if (event.key === 'ArrowRight' && current < slides.length - 1) {
      event.preventDefault();
      showSlide(current + 1);
      previous.focus();
    }
  });

  showSlide(current);
})();

const pippalaNoteDialog = document.getElementById('pippalaNoteDialog');
document.addEventListener('click', (event) => {
  const trigger = event.target.closest('[data-note-open]');
  if (trigger) {
    event.preventDefault();
    pippalaNoteDialog.showModal();
  }
});
pippalaNoteDialog.addEventListener('click', (event) => {
  if (event.target === pippalaNoteDialog || event.target.closest('.modal-close')) {
    pippalaNoteDialog.close();
  }
});
document.addEventListener('keydown', (event) => {
  if (event.key === 'Escape' && pippalaNoteDialog.open) {
    event.preventDefault();
    pippalaNoteDialog.close();
  }
});
